 body+='<text x="75" y="284">地震道编号 →　1 … 24</text><text x="3" y="16">采样号↓</text><text x="24" y="30">0</text><text x="24" y="110">8</text><text x="16" y="190">16</text><text x="16" y="260">23</text><text x="375" y="60">+1</text><rect x="382" y="75" width="35" height="25" fill="#946238"/><rect x="382" y="103" width="35" height="25" fill="#f8f8f8"/><rect x="382" y="131" width="35" height="25" fill="#3a6c9e"/><text x="375" y="180">−1（归一化）</text><text x="375" y="220">除以本窗</text><text x="375" y="244">最大绝对振幅</text>';
